import{_ as t,o as a,c as r,ag as n}from"./chunks/framework.DqVSm8kp.js";const m=JSON.parse(`{"title":"Module 1 : Qu'est-ce qu'un token ?","description":"","frontmatter":{},"headers":[],"relativePath":"fr/community/educators/module-1.md","filePath":"fr/community/educators/module-1.md"}`),o={name:"fr/community/educators/module-1.md"};function i(s,e,l,u,d,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="module-1-qu-est-ce-qu-un-token" tabindex="-1">Module 1 : Qu&#39;est-ce qu&#39;un token ? <a class="header-anchor" href="#module-1-qu-est-ce-qu-un-token" aria-label="Permalink to &quot;Module 1 : Qu&#39;est-ce qu&#39;un token ?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>L&#39;Observateur</strong> — Voir l&#39;invisible</p><p><strong>Duree :</strong> 45 min | <strong>Difficulte :</strong> Debutant | <strong>Prerequis :</strong> Aucun</p></div><h2 id="le-moment-eureka" tabindex="-1">Le Moment Eureka <a class="header-anchor" href="#le-moment-eureka" aria-label="Permalink to &quot;Le Moment Eureka&quot;">​</a></h2><blockquote><p>L&#39;IA ne pense pas en mots. Elle pense en tokens. Et les tokens ne sont pas ce que vous imaginez.</p></blockquote><p>C&#39;est l&#39;intuition fondamentale qui change tout dans la comprehension des modeles de langage par les etudiants. Chaque concept qui suit — temperature, fenetres de contexte, embeddings, tool calling — repose sur la comprehension de ce que sont reellement les tokens.</p><hr><h2 id="contexte-conceptuel" tabindex="-1">Contexte Conceptuel <a class="header-anchor" href="#contexte-conceptuel" aria-label="Permalink to &quot;Contexte Conceptuel&quot;">​</a></h2><h3 id="qu-est-ce-qu-un-token" tabindex="-1">Qu&#39;est-ce qu&#39;un token ? <a class="header-anchor" href="#qu-est-ce-qu-un-token" aria-label="Permalink to &quot;Qu&#39;est-ce qu&#39;un token ?&quot;">​</a></h3><p>Un <strong>token</strong> est la plus petite unite de texte traitee par un modele de langage. Les tokens ne sont ni des mots, ni des caracteres, ni des syllabes — ce sont des <strong>unites sous-lexicales</strong> determinees par un algorithme statistique entraine sur un large corpus.</p><p>L&#39;algorithme dominant est le <strong>Byte-Pair Encoding (BPE)</strong>, introduit en NLP par Sennrich et al. (2016). Le BPE commence par les caracteres individuels et fusionne iterativement les paires adjacentes les plus frequentes jusqu&#39;a atteindre une taille de vocabulaire cible (generalement 32 000 a 128 000 tokens).</p><p>Par exemple, le mot &quot;understanding&quot; pourrait etre tokenise ainsi :</p><ul><li><code>[&quot;under&quot;, &quot;stand&quot;, &quot;ing&quot;]</code> (3 tokens)</li></ul><p>Tandis que &quot;AI&quot; pourrait donner :</p><ul><li><code>[&quot;AI&quot;]</code> (1 token — suffisamment courant pour constituer une entree unique)</li></ul><h3 id="pourquoi-la-tokenisation-est-elle-importante" tabindex="-1">Pourquoi la tokenisation est-elle importante ? <a class="header-anchor" href="#pourquoi-la-tokenisation-est-elle-importante" aria-label="Permalink to &quot;Pourquoi la tokenisation est-elle importante ?&quot;">​</a></h3><p>Chaque aspect du comportement des LLM se mesure en tokens :</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Impact des tokens</th></tr></thead><tbody><tr><td><strong>Cout</strong></td><td>La tarification des API se fait au token</td></tr><tr><td><strong>Vitesse</strong></td><td>Les modeles generent un token par etape d&#39;inference</td></tr><tr><td><strong>Fenetre de contexte</strong></td><td>Le nombre maximum de tokens que le modele peut voir en une fois</td></tr><tr><td><strong>Qualite</strong></td><td>Les frontieres de tokens affectent ce que le modele peut &quot;voir&quot; a l&#39;interieur d&#39;un mot</td></tr><tr><td><strong>Equite</strong></td><td>Les langues ayant moins de tokens dans le vocabulaire necessitent plus de tokens par phrase</td></tr></tbody></table><h3 id="comment-fonctionne-le-bpe-simplifie" tabindex="-1">Comment fonctionne le BPE (simplifie) <a class="header-anchor" href="#comment-fonctionne-le-bpe-simplifie" aria-label="Permalink to &quot;Comment fonctionne le BPE (simplifie)&quot;">​</a></h3><ol><li>Commencer avec tous les octets individuels (256 tokens de base)</li><li>Compter toutes les paires adjacentes dans le corpus d&#39;entrainement</li><li>Fusionner la paire la plus frequente en un nouveau token</li><li>Repeter jusqu&#39;a atteindre la taille de vocabulaire cible</li></ol><p>Cela signifie :</p><ul><li>Les mots courants deviennent des tokens uniques : <code>&quot;the&quot;</code>, <code>&quot;and&quot;</code>, <code>&quot;is&quot;</code></li><li>Les mots rares sont decomposes en morceaux : <code>&quot;tokenization&quot;</code> → <code>[&quot;token&quot;, &quot;ization&quot;]</code></li><li>Les mots tres rares sont reduits a des caracteres individuels</li></ul><p>La famille LLaMA 3 utilise un tokenizer BPE avec un vocabulaire de 128 000 tokens, entraine principalement sur du texte anglais (Grattafiori et al., 2024).</p><hr><h2 id="exercices-pratiques" tabindex="-1">Exercices Pratiques <a class="header-anchor" href="#exercices-pratiques" aria-label="Permalink to &quot;Exercices Pratiques&quot;">​</a></h2><h3 id="exercice-1-voir-les-tokens-arriver-en-temps-reel" tabindex="-1">Exercice 1 : Voir les tokens arriver en temps reel <a class="header-anchor" href="#exercice-1-voir-les-tokens-arriver-en-temps-reel" aria-label="Permalink to &quot;Exercice 1 : Voir les tokens arriver en temps reel&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Ouvrez <strong>Chat Diagnostics</strong> dans LLMxRay et selectionnez un modele (ex. <code>llama3.2</code>)</li><li>Envoyez : <em>&quot;Explain what gravity is in one sentence&quot;</em></li><li>Observez les tokens arriver un par un — chaque token apparait au fur et a mesure que le modele le produit</li><li>Ouvrez l&#39;onglet <strong>Stream</strong> — voyez chaque token avec son horodatage et sa latence inter-token</li><li>Remarquez la <strong>coloration de confiance</strong> : les tokens verts sont arrives rapidement (confiance elevee), les tokens orange/rouges sont arrives lentement (confiance plus faible)</li></ol><p><strong>Ce qu&#39;il faut observer :</strong></p><ul><li>Les tokens ne sont pas toujours des mots complets. Vous verrez des mots partiels, de la ponctuation et des espaces comme tokens separes.</li><li>Certains tokens arrivent presque instantanement (le modele etait tres certain). D&#39;autres prennent plus de temps (le modele &quot;choisissait&quot; entre plusieurs options).</li><li>Le premier token prend le plus de temps (Time to First Token / TTFT) — c&#39;est le moment ou le modele traite l&#39;integralite de votre prompt.</li></ul><div class="info custom-block"><p class="custom-block-title">Qu&#39;est-ce que la coloration de confiance ?</p><p>LLMxRay estime la confiance des tokens a partir de la <strong>latence inter-token</strong>. Une generation plus rapide suggere que le modele avait une prediction dominante pour le token suivant. C&#39;est une approximation pratique — pour une mesure de confiance mathematiquement precise, la fonctionnalite Benchmark utilise de vrais logprobs via l&#39;endpoint compatible OpenAI. Voir le Module 3 pour l&#39;histoire complete sur la confiance et la verite.</p></div><hr><h3 id="exercice-2-le-choc-du-tokenizer" tabindex="-1">Exercice 2 : Le choc du tokenizer <a class="header-anchor" href="#exercice-2-le-choc-du-tokenizer" aria-label="Permalink to &quot;Exercice 2 : Le choc du tokenizer&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Dans le chat, demandez : <em>&quot;Count the letters in the word &#39;strawberry&#39;&quot;</em></li><li>Le modele dira probablement 10 — mais <code>strawberry</code> contient 10 lettres dont 3 r. Beaucoup de modeles comptent 2 r au lieu de 3.</li><li>Maintenant demandez : <em>&quot;How many words are in this sentence: The quick brown fox jumps over the lazy dog&quot;</em></li><li>Le modele repond correctement (9 mots) — compter les mots est plus facile que compter les lettres</li></ol><p><strong>Pourquoi cela se produit :</strong></p><p>Le mot <code>strawberry</code> est tokenise en quelque chose comme <code>[&quot;str&quot;, &quot;aw&quot;, &quot;berry&quot;]</code> — le modele ne voit jamais les lettres individuelles. Il traite ces morceaux comme des unites atomiques. Compter les lettres necessite un raisonnement au niveau des caracteres, mais le modele opere au niveau des tokens.</p><p>Ce n&#39;est pas un bug — c&#39;est une consequence fondamentale de la tokenisation sous-lexicale. Le modele ne peut litteralement pas &quot;voir&quot; les lettres individuelles a l&#39;interieur d&#39;un token.</p><div class="tip custom-block"><p class="custom-block-title">Essayez par vous-meme</p><p>Visitez le <a href="https://tiktokenizer.vercel.app/" target="_blank" rel="noreferrer">playground Tiktokenizer</a> ou le <a href="https://huggingface.co/spaces/Xenova/the-tokenizer-playground" target="_blank" rel="noreferrer">HuggingFace Tokenizer Playground</a> pour visualiser comment differents modeles tokenisent le meme texte. Comparez comment <code>llama</code> et <code>gpt-4</code> tokenisent <code>&quot;strawberry&quot;</code> — ils peuvent le decouper differemment.</p></div><p><strong>Contexte de recherche :</strong> Fu et al. (2024) ont mene une etude systematique de ce phenomene dans leur article <em>&quot;Why Do Large Language Models Struggle to Count Letters?&quot;</em> Ils ont decouvert que les erreurs correlent fortement avec la frequence des lettres et la longueur des mots, et non avec la frequence d&#39;apparition du mot dans les donnees d&#39;entrainement — confirmant que la limitation est architecturale (tokenisation), et non un manque de connaissances.</p><hr><h3 id="exercice-3-le-biais-linguistique-de-la-tokenisation" tabindex="-1">Exercice 3 : Le biais linguistique de la tokenisation <a class="header-anchor" href="#exercice-3-le-biais-linguistique-de-la-tokenisation" aria-label="Permalink to &quot;Exercice 3 : Le biais linguistique de la tokenisation&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Envoyez ce prompt au modele : <em>&quot;Say hello in one sentence&quot;</em></li><li>Ouvrez l&#39;onglet <strong>Stream</strong> et comptez les tokens dans la reponse</li><li>Maintenant envoyez : <em>&quot;Dis bonjour en une phrase&quot;</em> (la meme demande en francais)</li><li>Comptez a nouveau les tokens — la reponse en francais utilisera probablement plus de tokens</li><li>Essayez la meme chose en allemand, espagnol, chinois, arabe ou toute autre langue que vous connaissez</li><li>Notez le nombre de tokens pour chaque langue</li></ol><p><strong>Ce que vous allez decouvrir :</strong></p><p>Le meme contenu semantique necessite <strong>significativement plus de tokens</strong> dans les langues autres que l&#39;anglais. Ce n&#39;est pas parce que le francais est &quot;plus complexe&quot; — c&#39;est parce que le vocabulaire du tokenizer a ete construit principalement a partir de texte anglais.</p><table tabindex="0"><thead><tr><th>Langue</th><th>Ratio typique de tokens par rapport a l&#39;anglais</th></tr></thead><tbody><tr><td>Anglais</td><td>1,0x (reference)</td></tr><tr><td>Francais</td><td>1,3-1,5x</td></tr><tr><td>Allemand</td><td>1,4-1,6x</td></tr><tr><td>Chinois</td><td>1,5-2,0x</td></tr><tr><td>Arabe</td><td>2,0-3,0x</td></tr><tr><td>Certaines langues africaines</td><td>Jusqu&#39;a 5-15x</td></tr></tbody></table><p><strong>Pourquoi c&#39;est important en pratique :</strong></p><ul><li>Un utilisateur francophone atteint la limite de la fenetre de contexte <strong>30 a 50 % plus tot</strong> qu&#39;un utilisateur anglophone</li><li>Les couts d&#39;API sont <strong>proportionnellement plus eleves</strong> pour les langues non anglophones</li><li>La generation est <strong>plus lente</strong> (plus de tokens a produire pour le meme contenu)</li><li>La qualite peut se degrader parce que le modele dispose de moins de &quot;tokens de reflexion&quot;</li></ul><div class="warning custom-block"><p class="custom-block-title">Ceci est un domaine de recherche actif</p><p>Petrov et al. (2023) ont montre dans leur article NeurIPS <em>&quot;Language Model Tokenizers Introduce Unfairness Between Languages&quot;</em> que le meme texte peut necessiter jusqu&#39;a <strong>15x plus de tokens</strong> dans certaines langues par rapport a l&#39;anglais, sur 17 tokenizers differents. Ce n&#39;est pas seulement une preoccupation theorique — cela a des implications reelles en termes de cout, de latence et de qualite.</p><p>Explorez leur <a href="https://aleksandarpetrov.github.io/tokenization-fairness/" target="_blank" rel="noreferrer">demo interactive</a> pour visualiser la disparite entre les langues.</p></div><hr><h3 id="exercice-4-vitesse-et-confiance" tabindex="-1">Exercice 4 : Vitesse et confiance <a class="header-anchor" href="#exercice-4-vitesse-et-confiance" aria-label="Permalink to &quot;Exercice 4 : Vitesse et confiance&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Menez plusieurs conversations avec le modele sur differents sujets</li><li>Pour chaque reponse, observez la coloration de confiance dans le flux de tokens</li><li>Remarquez les schemas recurrents : <ul><li>Phrases courantes (&quot;I think&quot;, &quot;The answer is&quot;) → vert (rapide, confiant)</li><li>Termes techniques, chiffres, noms propres → plus orange (plus lent, moins certain)</li><li>Formulations creatives ou inhabituelles → orange/rouge majoritaire (le plus lent, le moins certain)</li></ul></li><li>Ouvrez deux onglets Stream cote a cote (de sessions differentes) et comparez les distributions de latence</li></ol><p><strong>Matiere a reflexion :</strong></p><ul><li>La vitesse (latence inter-token) est un <strong>indicateur indirect</strong> de la confiance, pas une mesure directe</li><li>Le modele genere les continuations &quot;evidentes&quot; plus rapidement que les continuations surprenantes</li><li>Cela reflete le fonctionnement de la distribution de probabilite softmax : lorsqu&#39;un token a une probabilite nettement superieure aux alternatives, le calcul converge plus rapidement</li><li>Pour une mesure de confiance <strong>precise</strong>, il faut les logprobs reels — que LLMxRay fournit via la fonctionnalite Benchmark (Module 3)</li></ul><hr><h2 id="points-cles" tabindex="-1">Points Cles <a class="header-anchor" href="#points-cles" aria-label="Permalink to &quot;Points Cles&quot;">​</a></h2><ol><li><strong>Les tokens sont l&#39;unite atomique</strong> du calcul des LLM — ni les mots, ni les caracteres</li><li><strong>La tokenisation BPE</strong> cree un vocabulaire a partir de schemas statistiques, pas de regles linguistiques</li><li><strong>Les frontieres de tokens</strong> determinent ce sur quoi le modele peut ou ne peut pas raisonner (comptage de lettres, manipulation de caracteres)</li><li><strong>Le biais linguistique</strong> des tokenizers cree une inegalite mesurable en termes de cout, vitesse et qualite entre les langues</li><li><strong>La vitesse correle avec la confiance</strong> mais n&#39;est pas identique — c&#39;est une approximation utile</li></ol><hr><h2 id="questions-de-discussion" tabindex="-1">Questions de Discussion <a class="header-anchor" href="#questions-de-discussion" aria-label="Permalink to &quot;Questions de Discussion&quot;">​</a></h2><p>Pour une discussion en classe ou en seminaire :</p><ol><li>Si les tokenizers sont entraines sur des corpus a dominante anglophone, a quoi ressemblerait un tokenizer multilingue &quot;equitable&quot; ? Est-ce meme possible avec une taille de vocabulaire fixe ?</li><li>Le probleme du &quot;strawberry&quot; montre que les modeles ne peuvent pas raisonner sur les caracteres a l&#39;interieur des tokens. Quelles autres taches apparemment simples pourraient etre affectees par les frontieres de tokens ?</li><li>Les entreprises d&#39;IA devraient-elles divulguer le biais linguistique de leur tokenizer ? Comment cela changerait-il la facon dont les utilisateurs non anglophones interagissent avec l&#39;IA ?</li><li>Si vous deviez concevoir un tokenizer pour un domaine specifique (medical, juridique, code), comment modifieriez-vous le processus d&#39;entrainement ?</li></ol><hr><h2 id="lectures-complementaires" tabindex="-1">Lectures Complementaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to &quot;Lectures Complementaires&quot;">​</a></h2><h3 id="articles-academiques" tabindex="-1">Articles academiques <a class="header-anchor" href="#articles-academiques" aria-label="Permalink to &quot;Articles academiques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Article</th><th>Auteurs</th><th>Annee</th><th>Lien</th></tr></thead><tbody><tr><td>Neural Machine Translation of Rare Words with Subword Units</td><td>Sennrich, Haddow, Birch</td><td>2016</td><td><a href="https://arxiv.org/abs/1508.07909" target="_blank" rel="noreferrer">arXiv:1508.07909</a></td></tr><tr><td>SentencePiece: A simple and language independent subword tokenizer</td><td>Kudo, Richardson</td><td>2018</td><td><a href="https://arxiv.org/abs/1808.06226" target="_blank" rel="noreferrer">arXiv:1808.06226</a></td></tr><tr><td>Language Model Tokenizers Introduce Unfairness Between Languages</td><td>Petrov, La Malfa, Torr, Bibi</td><td>2023</td><td><a href="https://arxiv.org/abs/2305.15425" target="_blank" rel="noreferrer">arXiv:2305.15425</a></td></tr><tr><td>Why Do Large Language Models Struggle to Count Letters?</td><td>Fu, Ferrando, Conde, Arriaga, Reviriego</td><td>2024</td><td><a href="https://arxiv.org/abs/2412.18626" target="_blank" rel="noreferrer">arXiv:2412.18626</a></td></tr><tr><td>Attention Is All You Need</td><td>Vaswani et al.</td><td>2017</td><td><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">arXiv:1706.03762</a></td></tr><tr><td>The Llama 3 Herd of Models</td><td>Grattafiori et al. (Meta AI)</td><td>2024</td><td><a href="https://arxiv.org/abs/2407.21783" target="_blank" rel="noreferrer">arXiv:2407.21783</a></td></tr></tbody></table><h3 id="tutoriels-et-explications-visuelles" tabindex="-1">Tutoriels et explications visuelles <a class="header-anchor" href="#tutoriels-et-explications-visuelles" aria-label="Permalink to &quot;Tutoriels et explications visuelles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ressource</th><th>Auteur</th><th>Lien</th></tr></thead><tbody><tr><td>Let&#39;s build the GPT Tokenizer (video, 2h13m)</td><td>Andrej Karpathy</td><td><a href="https://www.youtube.com/watch?v=zduSFxRajkE" target="_blank" rel="noreferrer">YouTube</a></td></tr><tr><td>The Illustrated Transformer</td><td>Jay Alammar</td><td><a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">jalammar.github.io</a></td></tr><tr><td>HuggingFace NLP Course, Chapter 6: Tokenizers</td><td>Hugging Face</td><td><a href="https://huggingface.co/learn/llm-course/en/chapter6/5" target="_blank" rel="noreferrer">huggingface.co/learn</a></td></tr><tr><td>LLM Sampling Parameters Explained</td><td>Let&#39;s Data Science</td><td><a href="https://letsdatascience.com/blog/llm-sampling-temperature-top-k-top-p-and-min-p-explained" target="_blank" rel="noreferrer">letsdatascience.com</a></td></tr></tbody></table><h3 id="outils-interactifs" tabindex="-1">Outils interactifs <a class="header-anchor" href="#outils-interactifs" aria-label="Permalink to &quot;Outils interactifs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Outil</th><th>Lien</th><th>Description</th></tr></thead><tbody><tr><td>Tiktokenizer</td><td><a href="https://tiktokenizer.vercel.app/" target="_blank" rel="noreferrer">tiktokenizer.vercel.app</a></td><td>Visualiser la tokenisation GPT avec un code couleur</td></tr><tr><td>HuggingFace Tokenizer Playground</td><td><a href="https://huggingface.co/spaces/Xenova/the-tokenizer-playground" target="_blank" rel="noreferrer">huggingface.co/spaces/Xenova</a></td><td>Comparer la tokenisation entre modeles ouverts (LLaMA, Mistral, etc.)</td></tr><tr><td>OpenAI Tokenizer</td><td><a href="https://platform.openai.com/tokenizer" target="_blank" rel="noreferrer">platform.openai.com/tokenizer</a></td><td>Visualiseur officiel de tokens OpenAI</td></tr></tbody></table><h3 id="cours-universitaires-associes" tabindex="-1">Cours universitaires associes <a class="header-anchor" href="#cours-universitaires-associes" aria-label="Permalink to &quot;Cours universitaires associes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Cours</th><th>Institution</th><th>Lien</th></tr></thead><tbody><tr><td>CS224N: NLP with Deep Learning</td><td>Stanford</td><td><a href="https://web.stanford.edu/class/cs224n/" target="_blank" rel="noreferrer">web.stanford.edu/class/cs224n</a></td></tr><tr><td>11-711: Advanced NLP</td><td>CMU</td><td><a href="https://www.phontron.com/class/anlp2024/" target="_blank" rel="noreferrer">phontron.com/class/anlp2024</a></td></tr></tbody></table><hr><h2 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Evaluation&quot;">​</a></h2><p><strong>Option A — Reflexion ecrite (individuel, 300 mots) :</strong> Decrivez un element de la tokenisation qui vous a surpris, en vous appuyant sur vos experiences dans LLMxRay (incluez des captures d&#39;ecran).</p><p><strong>Option B — Analyse de donnees (individuel ou en binome, 1 page) :</strong> Tokenisez le meme paragraphe dans 4 langues ou plus a l&#39;aide du HuggingFace Tokenizer Playground. Presentez un tableau des nombres de tokens, calculez les ratios par rapport a l&#39;anglais et discutez des implications en termes d&#39;equite.</p><p><strong>Option C — Presentation (groupes de 2-3, 5 minutes) :</strong> Concevez et presentez un &quot;defi de tokenisation&quot; — une tache que les LLM devraient pouvoir accomplir mais ne peuvent pas a cause des frontieres de tokens. Faites-en la demonstration en direct dans LLMxRay et expliquez pourquoi le tokenizer est le goulot d&#39;etranglement.</p><hr><h2 id="la-suite" tabindex="-1">La suite <a class="header-anchor" href="#la-suite" aria-label="Permalink to &quot;La suite&quot;">​</a></h2><p>Dans le <strong><a href="./module-2.html">Module 2 : Comment fonctionne la temperature ?</a></strong>, vous utiliserez ce que vous avez appris sur les tokens pour comprendre comment le modele <em>choisit</em> entre eux. La temperature controle la distribution de probabilite sur le vocabulaire — et vous decouvrirez que ce n&#39;est pas un curseur lineaire mais une transition de phase.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 1 sur 8</strong> du Kit Enseignants LLMxRay <a href="./index.html">Retour au programme</a> | <a href="./module-2.html">Suivant : Module 2 — Comment fonctionne la temperature ? →</a></p></div>',82)])])}const h=t(o,[["render",i]]);export{m as __pageData,h as default};
